<?php $title='Gerenciar usuários'; require __DIR__.'/layout.php'; ?><h1>Usuários cadastrados</h1><p>Total: <?= e($listing['total']) ?></p><form method="get" action="<?= e(url('admin-users')) ?>"><label>Pesquisar por nome ou e-mail<input name="q" maxlength="100" value="<?= e($_GET['q']??'') ?>"></label><button>Pesquisar</button></form><div class="admin-table"><table><thead><tr><th>Nome</th><th>E-mail</th><th>Perfil</th><th>Criado em</th><th>Ação</th></tr></thead><tbody><?php foreach($listing['items'] as $account): ?><tr><td><?= e($account['nome']) ?></td><td><?= e($account['email']) ?></td><td><?= e($account['perfil']) ?></td><td><?= e($account['criado_em']) ?></td><td><?php if($account['perfil']==='user'): ?><form method="post" action="<?= e(url('admin-user-delete')) ?>" data-confirm="Excluir esta conta e todos os seus dados de sono associados?"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= e($account['id']) ?>"><button class="link danger">Excluir conta</button></form><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php $pages=max(1,(int)ceil($listing['total']/20));for($p=1;$p<=$pages;$p++): ?><a href="<?= e(url('admin-users?q='.rawurlencode((string)($_GET['q']??'')).'&page='.$p)) ?>"><?= $p ?></a><?php endfor; ?><?php require __DIR__.'/end.php'; ?>
